package com.sigtm.backend.service;
import com.sigtm.backend.exception.ResourceNotFoundException; import com.sigtm.backend.model.*; import com.sigtm.backend.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class PoliticaReposicionService { private final PoliticaReposicionRepository policies; private final ProductoRepository products; private final ProveedorRepository suppliers; private final AuditoriaService audit;
 @Transactional(readOnly=true) public List<PoliticaReposicion> listar(){return policies.findByActiveTrue();}
 @Transactional public PoliticaReposicion guardar(Long productId,Long supplierId,PoliticaReposicion data){Producto p=products.findById(productId).orElseThrow(()->new ResourceNotFoundException("Producto no encontrado")); Proveedor s=supplierId==null?null:suppliers.findById(supplierId).orElseThrow(()->new ResourceNotFoundException("Proveedor no encontrado")); PoliticaReposicion x=policies.findByProductId(productId).orElse(PoliticaReposicion.builder().product(p).build()); x.setPreferredSupplier(s);x.setReorderPoint(data.getReorderPoint());x.setMinimumLot(data.getMinimumLot());x.setTargetStock(data.getTargetStock());x.setLeadTimeDays(data.getLeadTimeDays());x.setActive(data.getActive()==null||data.getActive()); x=policies.save(x);audit.registrar("UPDATE","POLITICA_REPOSICION",x.getId(),"Política para "+p.getCode());return x;}}
